section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/async-11-note.json",
  "title": "Async11Note",
  "type": "object",
  "required": ["pair_id", "cycle_iso", "header", "channel", "sync_infeasibility", "prompts", "posting", "ic_response", "pm_ack", "escalation"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "datetime": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?(Z|[+-][0-9]{2}:[0-9]{2})$"},
    "next_action": {
      "type": "object",
      "required": ["action", "owner_role", "deadline_sprint"],
      "properties": {
        "action": {"type": "string", "minLength": 5},
        "owner_role": {"type": "string", "minLength": 2},
        "deadline_sprint": {"type": "string", "pattern": "^S[0-9]+$"}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "pair_id": {"type": "string", "pattern": "^[a-z0-9._-]+--[a-z0-9._-]+$"},
    "cycle_iso": {"type": "string", "pattern": "^[0-9]{4}-W[0-9]{2}$"},
    "header": {
      "type": "object",
      "required": ["owner", "version", "last_reviewed", "response_window_business_hours"],
      "additionalProperties": false,
      "properties": {
        "owner": {"type": "object", "required": ["role", "person"], "properties": {"role": {"type": "string", "minLength": 2}, "person": {"type": "string", "minLength": 2}}},
        "version": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+(\\.[0-9]+)?$"},
        "last_reviewed": {"$ref": "#/definitions/date"},
        "response_window_business_hours": {"type": "integer", "minimum": 24, "maximum": 168}
      }
    },
    "channel": {
      "type": "object",
      "required": ["kind", "visible_to", "morale_shared_outside_pair"],
      "properties": {
        "kind": {"enum": ["private_doc", "dm", "email"]},
        "visible_to": {"type": "array", "minItems": 2, "maxItems": 2, "uniqueItems": true, "items": {"enum": ["pm", "ic"]}},
        "morale_shared_outside_pair": {"const": false}
      }
    },
    "sync_infeasibility": {
      "type": "object",
      "required": ["reason", "consecutive_async_cycles"],
      "properties": {
        "reason": {"enum": ["no_overlapping_hours", "temporary_leave", "sickness", "travel"]},
        "consecutive_async_cycles": {"type": "integer", "minimum": 1, "maximum": 3},
        "last_sync_call_cycle": {"type": "string", "pattern": "^[0-9]{4}-W[0-9]{2}$"}
      }
    },
    "prompts": {
      "type": "object",
      "required": ["blockers", "decisions_needed", "morale"],
      "additionalProperties": false,
      "properties": {
        "blockers": {"type": "string", "minLength": 10, "pattern": "(?i)(wbs|ticket|id\\b)", "not": {"pattern": "(?i)(anything to share|how is it going|how are things|all good)"}},
        "decisions_needed": {"type": "string", "minLength": 10, "pattern": "(?i)(whom|who|owner)", "not": {"pattern": "(?i)(anything to share|how is it going|how are things)"}},
        "morale": {"type": "string", "minLength": 10, "allOf": [{"pattern": "(?i)workload"}, {"pattern": "(?i)autonomy"}, {"pattern": "(?i)clarity"}, {"pattern": "1-10|1 to 10"}]}
      }
    },
    "posting": {
      "type": "object",
      "required": ["ic_timezone", "posted_at", "window_closes_at", "reminders_sent"],
      "properties": {
        "ic_timezone": {"type": "string", "pattern": "^[A-Za-z_]+/[A-Za-z_/+-]+$|^UTC$"},
        "posted_at": {"anyOf": [{"$ref": "#/definitions/datetime"}, {"type": "null"}]},
        "window_closes_at": {"anyOf": [{"$ref": "#/definitions/datetime"}, {"type": "null"}]},
        "reminders_sent": {"type": "integer", "minimum": 0}
      }
    },
    "ic_response": {
      "type": "object",
      "required": ["status", "received_at", "blockers", "decisions_needed", "morale"],
      "properties": {
        "status": {"enum": ["answered", "unresponsive", "paused"]},
        "received_at": {"anyOf": [{"$ref": "#/definitions/datetime"}, {"type": "null"}]},
        "authored_by": {"const": "ic"},
        "blockers": {"type": "string"},
        "decisions_needed": {"type": "string"},
        "morale": {"type": "string"},
        "leave_type": {"enum": ["vacation", "parental", "sick"]}
      },
      "allOf": [
        {"if": {"properties": {"status": {"const": "answered"}}}, "then": {"required": ["authored_by"], "properties": {"received_at": {"type": "string"}, "morale": {"pattern": "(?i)workload ?[0-9]+.*autonomy ?[0-9]+.*clarity ?[0-9]+"}}}},
        {"if": {"properties": {"status": {"const": "paused"}}}, "then": {"required": ["leave_type"], "properties": {"received_at": {"type": "null"}}}}
      ]
    },
    "pm_ack": {
      "type": "object",
      "required": ["acked_at", "ack_business_hours_after_response", "next_actions"],
      "properties": {
        "acked_at": {"anyOf": [{"$ref": "#/definitions/datetime"}, {"type": "null"}]},
        "ack_business_hours_after_response": {"type": ["integer", "null"], "minimum": 0, "maximum": 24},
        "next_actions": {"type": "array", "items": {"$ref": "#/definitions/next_action"}}
      }
    },
    "escalation": {
      "type": "object",
      "required": ["count_before_cycle", "unresponsive_count", "action"],
      "properties": {
        "count_before_cycle": {"type": "integer", "minimum": 0},
        "unresponsive_count": {"type": "integer", "minimum": 0},
        "action": {"enum": ["none", "synchronous_reschedule", "escalate_to_manager"]},
        "sync_slot_offered_for_cycle": {"type": "string", "pattern": "^[0-9]{4}-W[0-9]{2}$"},
        "manager_packet": {
          "type": "object",
          "required": ["manager", "unresponsive_count", "last_acked_next_actions", "includes_morale"],
          "properties": {
            "manager": {"type": "string", "minLength": 2},
            "unresponsive_count": {"type": "integer", "minimum": 2},
            "last_acked_next_actions": {"type": "array", "items": {"$ref": "#/definitions/next_action"}},
            "includes_morale": {"const": false}
          }
        }
      },
      "allOf": [
        {"if": {"properties": {"unresponsive_count": {"const": 0}}}, "then": {"properties": {"action": {"const": "none"}}}},
        {"if": {"properties": {"unresponsive_count": {"const": 1}}}, "then": {"properties": {"action": {"const": "synchronous_reschedule"}}, "required": ["sync_slot_offered_for_cycle"]}},
        {"if": {"properties": {"unresponsive_count": {"minimum": 2}}}, "then": {"properties": {"action": {"const": "escalate_to_manager"}}, "required": ["manager_packet"]}}
      ]
    },
    "review": {
      "type": "object",
      "required": ["computed_at", "cycles_in_quarter", "in_window_responses", "response_rate", "below_80_over_4_cycles", "structural_decision", "version_after"],
      "properties": {
        "computed_at": {"$ref": "#/definitions/date"},
        "cycles_in_quarter": {"type": "integer", "minimum": 1},
        "in_window_responses": {"type": "integer", "minimum": 0},
        "response_rate": {"type": "number", "minimum": 0, "maximum": 1},
        "below_80_over_4_cycles": {"type": "boolean"},
        "structural_decision": {"enum": ["none", "change_response_window", "restructure_pair", "mandate_synchronous"]},
        "version_after": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+(\\.[0-9]+)?$"}
      },
      "if": {"properties": {"below_80_over_4_cycles": {"const": true}}},
      "then": {"properties": {"structural_decision": {"enum": ["change_response_window", "restructure_pair", "mandate_synchronous"]}}}
    }
  }
}

example.code:
{
  "pair_id": "olena.k--taras.v",
  "cycle_iso": "2026-W21",
  "header": {
    "owner": {"role": "pm", "person": "olena.k"},
    "version": "1.4.0",
    "last_reviewed": "2026-04-07",
    "response_window_business_hours": 48
  },
  "channel": {"kind": "private_doc", "visible_to": ["pm", "ic"], "morale_shared_outside_pair": false},
  "sync_infeasibility": {"reason": "no_overlapping_hours", "consecutive_async_cycles": 2, "last_sync_call_cycle": "2026-W19"},
  "prompts": {
    "blockers": "What is blocking your current sprint goals? Cite the WBS id or ticket and what is upstream of it.",
    "decisions_needed": "What decision are you waiting on, from whom, and by which date?",
    "morale": "Workload 1-10, autonomy 1-10, clarity 1-10, and anything else you want me to know."
  },
  "posting": {"ic_timezone": "Australia/Sydney", "posted_at": "2026-05-18T09:00+10:00", "window_closes_at": "2026-05-20T09:00+10:00", "reminders_sent": 0},
  "ic_response": {
    "status": "answered",
    "received_at": "2026-05-19T16:30+10:00",
    "authored_by": "ic",
    "blockers": "PR review on WBS 4.2 stalled 3 days; waiting on backend-lead",
    "decisions_needed": "Token TTL for the session service; owner security-lead; needed before S14 planning",
    "morale": "workload 7, autonomy 8, clarity 6; clarity dropped because the S14 scope changed twice"
  },
  "pm_ack": {
    "acked_at": "2026-05-19T18:00+02:00",
    "ack_business_hours_after_response": 6,
    "next_actions": [
      {"action": "Ask backend-lead to review the WBS 4.2 PR today or hand it to a second reviewer", "owner_role": "pm", "deadline_sprint": "S13"},
      {"action": "Get security-lead's token TTL decision on the record before S14 planning", "owner_role": "pm", "deadline_sprint": "S14"}
    ]
  },
  "escalation": {"count_before_cycle": 0, "unresponsive_count": 0, "action": "none"},
  "review": {
    "computed_at": "2026-04-07",
    "cycles_in_quarter": 12,
    "in_window_responses": 11,
    "response_rate": 0.9167,
    "below_80_over_4_cycles": false,
    "structural_decision": "none",
    "version_after": "1.4.0"
  }
}

